ddl:
CREATE TABLE Airline (
    NAME VARCHAR(255) NOT NULL PRIMARY KEY ,
    HQLocation VARCHAR(255),
    Logo VARCHAR(255)
);

CREATE TABLE AirportAbbreviation (
    ABBV VARCHAR(8) NOT NULL PRIMARY KEY 
);

CREATE TABLE Airport (
    airportAbbv VARCHAR(8) NOT NULL PRIMARY KEY ,
    airportName VARCHAR(255),
    airportLocation VARCHAR(255),
    radioOperator VARCHAR(255),
    FOREIGN KEY (airportAbbv) REFERENCES AirportAbbreviation(ABBV)
);

CREATE TABLE AirportAirline (
    airportAbbv VARCHAR(8) NOT NULL,
    airlineName VARCHAR(255) NOT NULL,
    LOCATION VARCHAR(255),
    PRIMARY KEY (airportAbbv, airlineName),
    FOREIGN KEY (airportAbbv) REFERENCES Airport(airportAbbv),
    FOREIGN KEY (airlineName) REFERENCES Airline(NAME)
);

CREATE TABLE Amenity (
    amenityCode INT NOT NULL PRIMARY KEY ,
    amenityName VARCHAR(255) UNIQUE NOT NULL
);

CREATE TABLE FlightCrew (
    crewID INT NOT NULL PRIMARY KEY ,
    crewSize INT
);

CREATE TABLE FlightSchedule (
    flightNo INT NOT NULL PRIMARY KEY ,
    airlineName VARCHAR(255) NOT NULL,
    schDeptTime TIME NOT NULL,
    schArrivalTime TIME NOT NULL,
    crewID INT NOT NULL,
    ORIGIN VARCHAR(8) NOT NULL,
    DESTINATION VARCHAR(8) NOT NULL,
    FOREIGN KEY (airlineName) REFERENCES Airline(NAME),
    FOREIGN KEY (crewID) REFERENCES FlightCrew(crewID),
    FOREIGN KEY (ORIGIN) REFERENCES Airport(airportAbbv),
    FOREIGN KEY (DESTINATION) REFERENCES Airport(airportAbbv)
);

CREATE TABLE Model (
    modelName VARCHAR(255) NOT NULL,
    MANUFACTURER VARCHAR(255) NOT NULL,
    numberOfPassengers INT,
    PRIMARY KEY (modelName, MANUFACTURER)
);

CREATE TABLE Airplane (
    tailNumber VARCHAR(10) NOT NULL PRIMARY KEY ,
    airlineName VARCHAR(255),
    modelName VARCHAR(255),
    MANUFACTURER VARCHAR(255),
    NICKNAME VARCHAR(255),
    FOREIGN KEY (airlineName) REFERENCES Airline(NAME),
    FOREIGN KEY (modelName, MANUFACTURER) REFERENCES Model(modelName, MANUFACTURER)
);

CREATE TABLE Role (
    rName VARCHAR(255) NOT NULL PRIMARY KEY 
);

CREATE TABLE CrewMember (
    faaNum INT NOT NULL PRIMARY KEY ,
    fName VARCHAR(255),
    lName VARCHAR(255),
    SEX VARCHAR(255),
    ROLE VARCHAR(255),
    FOREIGN KEY (ROLE) REFERENCES Role(rName)
);

CREATE TABLE FlightCrew_CrewMember (
    crewID INT NOT NULL ,
    faaNum INT NOT NULL,
    presentRole VARCHAR(255),
    PRIMARY KEY (crewID, faaNum),
    FOREIGN KEY (crewID) REFERENCES FlightCrew(crewID),
    FOREIGN KEY (faaNum) REFERENCES CrewMember(faaNum)
);

CREATE TABLE Status (
    statusName VARCHAR(255) NOT NULL PRIMARY KEY 
);

CREATE TABLE FlightInstance (
    flightInstanceID INT NOT NULL PRIMARY KEY ,
    flightNo INT NOT NULL UNIQUE,
    tailNumber VARCHAR(10) NOT NULL,
    STATUS VARCHAR(255),
    departureDate DATE,
    departureTime TIME,
    arrivalTime TIME,
    numberRegisteredPassengers INT,
    FOREIGN KEY (flightNo) REFERENCES FlightSchedule(flightNo),
    FOREIGN KEY (tailNumber) REFERENCES Airplane(tailNumber),
    FOREIGN KEY (STATUS) REFERENCES Status(statusName)
);

CREATE TABLE ChargableInstance (
    flightInstanceID INT NOT NULL PRIMARY KEY ,
    FOREIGN KEY (flightInstanceID) REFERENCES FlightInstance(flightInstanceID)
);

CREATE TABLE AmenityChargableInstance (
    amenityCode INT NOT NULL,
    flightInstanceID INT NOT NULL,
    PRIMARY KEY (amenityCode, flightInstanceID),
    FOREIGN KEY (amenityCode) REFERENCES Amenity(amenityCode),
    FOREIGN KEY (flightInstanceID) REFERENCES ChargableInstance(flightInstanceID)
);

CREATE TABLE DomesticInstance (
    flightInstanceID INT NOT NULL PRIMARY KEY ,
    FOREIGN KEY (flightInstanceID) REFERENCES ChargableInstance(flightInstanceID)
);

CREATE TABLE IncidentReport (
    IncidentID INT NOT NULL PRIMARY KEY ,
    flightInstanceID INT NOT NULL,
    reporterFAANo INT NOT NULL,
    reportedFAANo INT NOT NULL,
    IncidentType INT NOT NULL,
    reportTime TIME NOT NULL,
    DESCRIPTION VARCHAR(255),
    FOREIGN KEY (flightInstanceID) REFERENCES FlightInstance(flightInstanceID)
);

CREATE TABLE InternationalInstance (
    flightInstanceID INT NOT NULL PRIMARY KEY ,
    FOREIGN KEY (flightInstanceID) REFERENCES FlightInstance(flightInstanceID)
);

CREATE TABLE LocalInstance (
    flightInstanceID INT NOT NULL PRIMARY KEY ,
    FOREIGN KEY (flightInstanceID) REFERENCES ChargableInstance(flightInstanceID)
);

CREATE TABLE PersonnelReport (
    incidentID INT NOT NULL,
    SENTIMENT VARCHAR(255) NOT NULL,
    reportedFAANo INT,
    PRIMARY KEY (incidentID, SENTIMENT),
    FOREIGN KEY (incidentID) REFERENCES IncidentReport(IncidentID)
);
